    data=ROOT/'docs/literature/omics-2023-2026';proof=json.loads((data/'cellphonedb-catalog-validation.json').read_bytes());assert proof['status']=='passed-fourteen-CellPhoneDB-related-roles-five-registry-additions-and-one-scoped-integration' and (proof['new_scoped_integrations'],proof['including_existing_adapters'],proof['missing_integrations'],proof['prior_reviews_preserved'],proof['reviewed_uses'],proof['supporting_pointers'],proof['named_tools'],proof['observations'])==(85,88,251,966,980,340,395,2457) and not proof['whole_goal_complete'] and not proof['whole_paper_reproduced'] and not proof['website_deployed'];assert pin(data/'cellphonedb-catalog-support.zip')==proof['archive'];files=unpack(data/'cellphonedb-catalog-support.zip',proof)
